logger = logging.getLogger("desktopenv.metrics.audacity")


def _read_wav_info(file_path):
    """Read basic WAV info using the stdlib wave module. Returns dict with
    'channels', 'sample_rate', 'n_frames', 'duration', 'sampwidth'."""
    with wave.open(file_path, "rb") as wf:
        channels = wf.getnchannels()
        sample_rate = wf.getframerate()
        n_frames = wf.getnframes()
        sampwidth = wf.getsampwidth()
        duration = n_frames / sample_rate if sample_rate > 0 else 0.0
        return {
            "channels": channels,
            "sample_rate": sample_rate,
            "n_frames": n_frames,
            "duration": duration,
            "sampwidth": sampwidth,
        }


def _read_wav_samples(file_path):
    """Read WAV samples as a list of floats in [-1.0, 1.0].
    For multi-channel, returns interleaved samples."""
    with wave.open(file_path, "rb") as wf:
        n_frames = wf.getnframes()
        channels = wf.getnchannels()
        sampwidth = wf.getsampwidth()
        raw = wf.readframes(n_frames)

    total_samples = n_frames * channels
    if sampwidth == 1:
        # 8-bit unsigned
        samples = struct.unpack(f"{total_samples}B", raw)
        return [(s - 128) / 128.0 for s in samples]
    elif sampwidth == 2:
        # 16-bit signed
        samples = struct.unpack(f"<{total_samples}h", raw)
        return [s / 32768.0 for s in samples]
    elif sampwidth == 3:
        # 24-bit signed
        result = []
        for i in range(total_samples):
            b = raw[i * 3: i * 3 + 3]
            val = int.from_bytes(b, byteorder="little", signed=True)
            result.append(val / 8388608.0)
        return result
    elif sampwidth == 4:
        # 32-bit signed
        samples = struct.unpack(f"<{total_samples}i", raw)
        return [s / 2147483648.0 for s in samples]
    else:
        raise ValueError(f"Unsupported sample width: {sampwidth}")


def _rms_db(samples):
    """Compute RMS in dB for a list of float samples."""
    if not samples:
        return -100.0
    mean_sq = sum(s * s for s in samples) / len(samples)
    rms = math.sqrt(mean_sq)
    if rms < 1e-10:
        return -100.0
    return 20.0 * math.log10(rms)


def _get_mono_samples(file_path):
    """Read WAV and return mono samples (average channels) + sample_rate."""
    info = _read_wav_info(file_path)
    samples = _read_wav_samples(file_path)
    channels = info["channels"]
    if channels > 1:
        mono = []
        for i in range(0, len(samples), channels):
            mono.append(sum(samples[i:i + channels]) / channels)
        return mono, info["sample_rate"]
    return samples, info["sample_rate"]


def _extract_time_range(samples, sr, start_time, end_time):
    """Extract samples in [start_time, end_time] seconds."""
    start_idx = int(start_time * sr)
    end_idx = int(end_time * sr)
    start_idx = max(0, min(start_idx, len(samples)))
    end_idx = max(0, min(end_idx, len(samples)))
    return samples[start_idx:end_idx]


def _resolve_reference_path(path):
    """Resolve a reference asset path from common evaluator working directories."""
    if os.path.isabs(path) and os.path.isfile(path):
        return path

    candidates = [
        os.path.abspath(path),
        os.path.abspath(os.path.join(os.path.dirname(__file__), path)),
    ]
    current = os.path.abspath(os.path.dirname(__file__))
    for _ in range(8):
        candidates.append(os.path.join(current, path))
        current = os.path.dirname(current)

    for candidate in candidates:
        if os.path.isfile(candidate):
            return candidate
    return None


def _paired_segments(a, b):
    length = min(len(a), len(b))
    return a[:length], b[:length]


def _rmse(a, b):
    a, b = _paired_segments(a, b)
    if not a:
        return float("inf")
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)) / len(a))


def _correlation(a, b):
    a, b = _paired_segments(a, b)
    if not a:
        return 0.0
    mean_a = sum(a) / len(a)
    mean_b = sum(b) / len(b)
    num = sum((x - mean_a) * (y - mean_b) for x, y in zip(a, b))
    den_a = math.sqrt(sum((x - mean_a) ** 2 for x in a))
    den_b = math.sqrt(sum((y - mean_b) ** 2 for y in b))
    if den_a < 1e-10 or den_b < 1e-10:
        return 0.0
    return num / (den_a * den_b)


def check_audio_duration(file_path, rule) -> float:
    """Check audio file duration.
    rule: {"expected_duration": float, "tolerance": float (default 0.5)}
    """
    try:
        if not os.path.isfile(file_path):
            logger.error(f"File not found: {file_path}")
            return 0.0
        info = _read_wav_info(file_path)
        expected = float(rule["expected_duration"])
        tolerance = float(rule.get("tolerance", 0.5))
        actual = info["duration"]
        logger.info(f"check_audio_duration: actual={actual:.2f}s, expected={expected:.2f}s, tol={tolerance:.2f}s")
        if abs(actual - expected) <= tolerance:
            return 1.0
        return 0.0
    except Exception as e:
        logger.error(f"check_audio_duration error: {e}")
        return 0.0


def check_interactive_audacity_ia01(file_path, rule) -> float:
    """IA-01 validator: partial denoise delivery.
    Ensures duration is preserved, the intro stays unchanged, and only the
    post-intro region is attenuated/changed relative to the source recording.
    """
    try:
        if not os.path.isfile(file_path):
            return 0.0

        duration_rule = {
            "expected_duration": float(rule["expected_duration"]),
            "tolerance": float(rule.get("duration_tolerance", 1.0)),
        }
        if check_audio_duration(file_path, duration_rule) < 1.0:
            return 0.0

        samples, sr = _get_mono_samples(file_path)
        intro = _extract_time_range(
            samples,
            sr,
            float(rule.get("intro_start", 0.0)),
            float(rule.get("intro_end", 2.0)),
        )
        tail = _extract_time_range(
            samples,
            sr,
            float(rule.get("tail_start", 2.0)),
            float(rule.get("tail_end", duration_rule["expected_duration"])),
        )

        if not intro or not tail:
            return 0.0

        intro_rms = _rms_db(intro)
        tail_rms = _rms_db(tail)
        intro_min = float(rule.get("intro_min_rms_db", -30.0))
        tail_min = float(rule.get("tail_min_rms_db", -38.0))
        logger.info(
            f"check_interactive_audacity_ia01: intro_rms={intro_rms:.2f}dB (min {intro_min}), "
            f"tail_rms={tail_rms:.2f}dB (min {tail_min})"
        )

        if intro_rms < intro_min:
            return 0.0
        if tail_rms < tail_min:
            return 0.0

        source_path = rule.get("source_path")
        if source_path:
            resolved_source = _resolve_reference_path(source_path)
            if not resolved_source:
                logger.error(f"Reference source file not found: {source_path}")
                return 0.0

            source_samples, source_sr = _get_mono_samples(resolved_source)
            if source_sr != sr:
                logger.error(f"Sample rate mismatch: actual={sr}, source={source_sr}")
                return 0.0

            source_intro = _extract_time_range(
                source_samples,
                source_sr,
                float(rule.get("intro_start", 0.0)),
                float(rule.get("intro_end", 2.0)),
            )
            source_tail = _extract_time_range(
                source_samples,
                source_sr,
                float(rule.get("tail_start", 2.0)),
                float(rule.get("tail_end", duration_rule["expected_duration"])),
            )
            if not source_intro or not source_tail:
                return 0.0

            intro_rmse = _rmse(intro, source_intro)
            intro_corr = _correlation(intro, source_intro)
            intro_rms_delta = abs(intro_rms - _rms_db(source_intro))
            max_intro_rmse = float(rule.get("max_intro_rmse", 0.01))
            min_intro_correlation = float(rule.get("min_intro_correlation", 0.995))
            max_intro_rms_delta_db = float(rule.get("max_intro_rms_delta_db", 1.0))
            logger.info(
                f"intro compare: rmse={intro_rmse:.6f} (max {max_intro_rmse}), "
                f"corr={intro_corr:.6f} (min {min_intro_correlation}), "
                f"rms_delta={intro_rms_delta:.2f}dB (max {max_intro_rms_delta_db})"
            )
            if intro_rmse > max_intro_rmse:
                return 0.0
            if intro_corr < min_intro_correlation:
                return 0.0
            if intro_rms_delta > max_intro_rms_delta_db:
                return 0.0

            tail_rmse = _rmse(tail, source_tail)
            source_tail_rms = _rms_db(source_tail)
            tail_reduction_db = source_tail_rms - tail_rms
            min_tail_rmse = float(rule.get("min_tail_rmse", 0.005))
            min_tail_rms_reduction_db = float(rule.get("min_tail_rms_reduction_db", 1.0))
            logger.info(
                f"tail compare: rmse={tail_rmse:.6f} (min {min_tail_rmse}), "
                f"source_tail_rms={source_tail_rms:.2f}dB, tail_reduction={tail_reduction_db:.2f}dB "
                f"(min {min_tail_rms_reduction_db})"
            )
            if tail_rmse < min_tail_rmse:
                return 0.0
            if tail_reduction_db < min_tail_rms_reduction_db:
                return 0.0
        return 1.0
    except Exception as e:
        logger.error(f"check_interactive_audacity_ia01 error: {e}")
        return 0.0
